export function minerWithinMobRange(enemy,p){return Math.abs(enemy.y-p.y)<500/8}
export function minerNearestThreat(enemies,p,homing=false){return enemies.filter(e=>Math.hypot(e.x-p.x,e.y-p.y)<(homing?34/8:(e.kind==='SKELETON'||e.kind==='GOLEM')?105/8:62/8)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0]||null}
export function minerCaveKind(roll,depth){return roll<.24?'CREEPER':roll<.44?'SKELETON':depth>=50&&roll<.58?'SPIDER':'ZOMBIE'}
export function minerCaveSpawn(world,p,depth,roll,offset=0){const spots=[];for(let y=Math.max(3,p.y-9);y<=Math.min(world.length-1,p.y+9);y++)for(let x=1;x<(world[y]?.length??1)-1;x++){const d=Math.abs(x-p.x)+Math.abs(y-p.y),v=world[y][x];if(d>=6&&d<=13&&!minerSolid(v)&&v!==7)spots.push({x,y})}if(!spots.length)return null;for(let i=0;i<Math.min(12,spots.length);i++){const c=spots[(offset+i)%spots.length];if(minerEnemyRoute(world,c,p)?.length){const kind=minerCaveKind(roll,depth),bonus=Math.floor(Math.floor(depth/50)/2),hp=(kind==='ZOMBIE'?4:kind==='SKELETON'?2:3)+bonus;return {kind,x:c.x,y:c.y,hp,t:0,age:0,shotCd:1.8,ambient:true}}}return null}
export function minerSkeletonShot(world,enemy,target,dt,depth){const dx=target.x-enemy.x,dy=target.y-enemy.y,d=Math.hypot(dx,dy);if(d<=2.25||d>=9.75||!minerLineClear(world,enemy,target))return null;enemy.shotCd-=dt;if(enemy.shotCd>0)return null;const tier=Math.floor(depth/50),min=Math.max(55,90-tier*8);enemy.shotCd=(min+Math.floor(Math.random()*(141-min)))/60;return {x:enemy.x+.5,y:enemy.y+.5,vx:dx/d*13.5,vy:dy/d*13.5,ttl:100/60,dmg:1,owner:'enemy',kind:'arrow'}}
export function minerGolemShot(world,enemy,target,dt){enemy.shotCd-=dt;const dx=target.x-enemy.x,dy=target.y-enemy.y,d=Math.hypot(dx,dy);if(enemy.shotCd>0||d<=3.75||d>=11.875||!minerLineClear(world,enemy,target))return null;enemy.shotCd=2.3;return {x:enemy.x+.5,y:enemy.y+.5,vx:dx/d*10.5,vy:dy/d*10.5,ttl:2,dmg:2,owner:'enemy'}}
export function minerGateReady(gates,p,cooldown,transit){return !transit&&cooldown<=0&&gates.some(g=>g&&p.x===g.x&&(p.y===g.y||p.y===g.y-1))}
export function minerTntTargets(trap,enemies,p){return {enemies:enemies.filter(e=>Math.hypot(e.x-trap.x,e.y-trap.y)<30/8),player:Math.hypot(p.x-trap.x,p.y-trap.y)<18/8}}
export function minerStagger(enemy){if(enemy.kind!=='GOLEM')enemy.stun=18/60}
export function minerMobTravelSeconds(kind,inWater=false){const speed=({SPIDER:.3,CREEPER:.23,SKELETON:.18,GOLEM:.13})[kind]??.2;return 8/(60*speed*(inWater?.55:1))}
export function minerSpiderStep(world,enemy,p,dt){enemy.lunge=Math.max(0,(enemy.lunge||0)-dt);const dx=p.x-enemy.x,dy=p.y-enemy.y,d=Math.hypot(dx,dy);if(enemy.lunge<=0&&d>14/8&&d<44/8&&minerLineClear(world,enemy,p)){enemy.lunge=110/60;const sx=Math.sign(dx),sy=Math.sign(dy),nx=enemy.x+sx,ny=enemy.y+sy;if(!minerSolid(world[enemy.y]?.[nx])&&world[enemy.y]?.[nx]!==undefined)enemy.x=nx;else if(!minerSolid(world[ny]?.[enemy.x])&&world[ny]?.[enemy.x]!==undefined)enemy.y=ny;return 'pounce'}return 'waiting'}
